    "impact.subtitle": "ತೋಟ ಮತ್ತು ಊಟದ ಮೇಜಿನ ನಡುವೆ ನೇರ ಸಂಪರ್ಕ ಕಲ್ಪಿಸುವ ಮೂಲಕ ನೈಸರ್ಗಿಕ ಕೃಷಿ ಮತ್ತು ಪಾರದರ್ಶಕತೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತೇವೆ.",
    "impact.card1Title": "ಸ್ಥಳೀಯ ರೈತರಿಗೆ ಬೆಂಬಲ",
    "impact.card1Desc": "ರೈತರಿಗೆ ನೇರ ಮಾರುಕಟ್ಟೆ ಅವಕಾಶ, ನ್ಯಾಯಯುತ ಬೆಲೆ ಮತ್ತು ಆರ್ಥಿಕ ಸ್ವಾಭಿಮಾನ ನೀಡುತ್ತದೆ.",
    "impact.card2Title": "ಮಧ್ಯವರ್ತಿಗಳ ಹಾವಳಿಗೆ ಮುಕ್ತಿ",
    "impact.card2Desc": "ಅನಗತ್ಯ ದಲ್ಲಾಳಿ ಕಮಿಷನ್ ರದ್ದುಪಡಿಸಿ, ಗ್ರಾಹಕರು ನೀಡುವ ಪೂರ್ಣ ಹಣ ನೇರವಾಗಿ ಬೆಳೆದ ರೈತರಿಗೆ ಸಿಗುತ್ತದೆ.",
    "impact.card3Title": "ತಾಜಾ ಮತ್ತು ಪೌಷ್ಟಿಕ ಆಹಾರ",
    "impact.card3Desc": "ರಾಸಾಯನಿಕ ರಹಿತ, ಮುಂಜಾನೆಯ ನೈಸರ್ಗಿಕ ಬೆಳೆಗಳು ಯಾವುದೇ ಕಲಬೆರಕೆಯಿಲ್ಲದೆ ಕುಟುಂಬಗಳಿಗೆ ತಲುಪುತ್ತವೆ.",
    "impact.card4Title": "ವಿಶ್ವಾಸಾರ್ಹ ನೇರ ಜಾಲ",
    "impact.card4Desc": "ರೈತರು ಮತ್ತು ಗ್ರಾಹಕರ ನಡುವೆ ಪಾರದರ್ಶಕತೆ ಮತ್ತು ವಿಶ್ವಾಸದ ನೈಜ ಬಾಂಧವ್ಯ ಬೆಳೆಸುತ್ತದೆ.",
    "impact.realImpact": "ನೇರ ಪ್ರಭಾವ",
    "why.badge": "ಆರಿಕ್ ಆರೋಹಿ ವೈಶಿಷ್ಟ್ಯಗಳು",
    "why.title1": "ಆರಿಕ್ ಆರೋಹಿ ಏಕೆ ಆಯ್ಕೆ ಮಾಡಬೇಕು?",
    "why.subtitle": "ರೈತರ ಸಬಲೀಕರಣ ಮತ್ತು ಗ್ರಾಹಕರಿಗೆ ಅತಿ ತಾಜಾ ಸಾವಯವ ಬೆಳೆಗಳನ್ನು ತಲುಪಿಸಲು ನಿರ್ಮಿಸಲಾಗಿದೆ.",
    "why.reason1Title": "ರೈತರೊಂದಿಗೆ ನೇರ ಸಂಪರ್ಕ",
    "why.reason1Desc": "ದಲ್ಲಾಳಿಗಳಿಲ್ಲದೆ ನೇರವಾಗಿ ಪ್ರಮಾಣೀಕೃತ ರೈತರಿಂದ ಖರೀದಿಸಿ, ರೈತರ ಕಠಿಣ ಶ್ರಮಕ್ಕೆ ಪೂರ್ಣ ಮೌಲ್ಯ ನೀಡಿ.",
    "why.reason2Title": "ತಾಜಾ ಮತ್ತು ಪತ್ತೆಹಚ್ಚಬಹುದಾದ ಬೆಳೆಗಳು",
    "why.reason2Desc": "ಮುಂಜಾನೆಯ ಕೊಯ್ಲು, ತೋಟದ ವಿವರ ಮತ್ತು ಸಂಪೂರ್ಣ ಪಾರದರ್ಶಕತೆಯೊಂದಿಗೆ ಮನೆಗೆ ತಲುಪುತ್ತದೆ.",
    "why.reason3Title": "ಪಾರದರ್ಶಕ ದರ ನಿಗದಿ",
    "why.reason3Desc": "ರೈತರೇ ನಿಗದಿಪಡಿಸುವ ನ್ಯಾಯಯುತ ದರಗಳು — ಗ್ರಾಹಕರಿಗೆ ಉಳಿತಾಯ, ರೈತರಿಗೆ ಸಮೃದ್ಧಿ.",
    "why.reason4Title": "ಸುರಕ್ಷಿತ ಆರ್ಡರ್ ವ್ಯವಸ್ಥೆ",
    "why.reason4Desc": "ನೈಜ ಆರ್ಡರ್ ಟ್ರ್ಯಾಕಿಂಗ್, ಲೈವ್ ಸ್ಥಿತಿ ಮತ್ತು ಅಧಿಕೃತ ಗ್ರಾಹಕ ವಿಮರ್ಶೆಗಳು.",
    "why.reason5Title": "ರೈತರಿಗೆ AI ಕೃಷಿ ಸಲಹೆಗಾರ",
    "why.reason5Desc": "ಬೆಳೆ ನಿರ್ವಹಣೆ, ಕೀಟ ನಿಯಂತ್ರಣ ಮತ್ತು ಮಾರುಕಟ್ಟೆ ದರಗಳ ಬಗ್ಗೆ ಬುದ್ಧಿವಂತ ಕೃಷಿ AI ಮಾರ್ಗದರ್ಶನ.",
    "why.reason6Title": "ಬಹುಭಾಷಾ ಅನುಭವ",
    "why.reason6Desc": "ಕನ್ನಡ, ಹಿಂದಿ, ತೆಲುಗು, ತಮಿಳು, ಮಲಯಾಳಂ ಮತ್ತು ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ಸಂಪೂರ್ಣ ಧ್ವನಿ ಮತ್ತು ಪಠ್ಯ ಬೆಂಬಲ.",
    "why.guarantee": "ಆರಿಕ್ ಆರೋಹಿ ಮಾನದಂಡ",
    "cta.badge": "ನೇರ ಕೃಷಿಯ ಭವಿಷ್ಯ",
    "cta.title1": "ಆರಿಕ್ ಆರೋಹಿ ಜೊತೆ ಬೆಳೆಯಿರಿ.",
    "cta.title2": "ತಾಜಾ ಬೆಳೆಗಳು. ನೇರ ಮೌಲ್ಯ.",
    "cta.subtitle": "ನೀವು ಉತ್ತಮ ಆದಾಯ ಬಯಸುವ ರೈತರಾಗಿರಲಿ ಅಥವಾ ತಾಜಾ ಪೌಷ್ಟಿಕ ಆಹಾರ ಬಯಸುವ ಗ್ರಾಹಕರಾಗಿರಲಿ, ಇಂದೇ ನಮ್ಮ ಜೊತೆ ಕೈಜೋಡಿಸಿ.",
