    "how.step2Sub": "வெளிப்படையான சந்தை",
    "how.step2Desc": "வாடிக்கையாளர்கள் புதிய இயற்கை பயிர்களைத் தேர்ந்தெடுத்து நேரடியாக ஆர்டர் செய்கிறார்கள்.",
    "how.step2Badge": "100% நம்பகமானது",
    "how.step3Title": "விவசாயிகள் ஆர்டரைத் தயாரிக்கிறார்கள்",
    "how.step3Sub": "புதிய அறுவடை தயாரிப்பு",
    "how.step3Desc": "ஆர்டர் வந்தவுடன் உடனடியாக புதிதாகப் பறித்துப் பேக் செய்யப்படுகிறது.",
    "how.step3Badge": "உயர்தரம்",
    "how.step4Title": "வாடிக்கையாளருக்கு டெலிவரி",
    "how.step4Sub": "நேரடி வீட்டு டெலிவரி",
    "how.step4Desc": "பண்ணையிலிருந்து நேரடியாக சில மணிநேரங்களில் வாடிக்கையாளரின் வீட்டிற்குச் சென்றடைகிறது.",
    "how.step4Badge": "நேரடி விநியோகம்",
    "how.tier": "படிநிலைத் தரம்",
    "impact.badge": "எங்கள் விவசாய தாக்கம்",
    "impact.title1": "விவசாய வர்த்தகத்தில் மாற்றம்.",
    "impact.title2": "விவசாய சமூகங்களின் வலிமை.",
    "impact.subtitle": "பண்ணைகளையும் வாடிக்கையாளர்களையும் நேரடியாக இணைப்பதன் மூலம் இயற்கை விவசாயத்தையும் வெளிப்படைத்தன்மையையும் வளர்க்கிறோம்.",
    "impact.card1Title": "உள்ளூர் விவசாயிகளுக்கு ஆதரவு",
    "impact.card1Desc": "விவசாயிகளுக்கு நேரடி சந்தை வாய்ப்பு, நியாயமான விலை மற்றும் பொருளாதார கௌரவம் வழங்குதல்.",
    "impact.card2Title": "இடைத்தரகர்கள் நீக்கம்",
    "impact.card2Desc": "அனாவசிய கமிஷன்களை நீக்கி, வாடிக்கையாளர் செலுத்தும் முழுப் பணமும் விவசாயிக்கு நேரடியாகச் சேர்கிறது.",
    "impact.card3Title": "புதிய மற்றும் ஆரோக்கியமான உணவு",
    "impact.card3Desc": "ரசாயனமற்ற, இயற்கையான விளைபொருட்கள் குடும்பங்களுக்கு தூய்மையாகக் கிடைக்கின்றன.",
    "impact.card4Title": "நம்பகமான நேரடி கட்டமைப்பு",
    "impact.card4Desc": "விவசாயிகளுக்கும் நுகர்வோருக்கும் இடையே வெளிப்படையான நம்பிக்கைப் பிணைப்பு.",
    "impact.realImpact": "நேரடி தாக்கம்",
    "why.badge": "ஆரிக் ஆரோஹிவின் சிறப்பு",
    "why.title1": "ஆரிக் ஆரோஹிவை ஏன் தேர்ந்தெடுக்க வேண்டும்?",
    "why.subtitle": "விவசாயிகளை மேம்படுத்தவும் வாடிக்கையாளர்களுக்கு உச்சபட்ச புதிய விளைபொருட்களை வழங்கவும் உருவாக்கப்பட்டது.",
    "why.reason1Title": "விவசாயிகளுடன் நேரடி தொடர்பு",
    "why.reason1Desc": "இடைத்தரகர்கள் இன்றி நேரடியாக சான்றளிக்கப்பட்ட விவசாயிகளிடமிருந்து வாங்கி அவர்களின் உழைப்புக்கு முழு மதிப்பளியுங்கள்.",
    "why.reason2Title": "புதிய மற்றும் கண்டறியக்கூடிய பயிர்கள்",
    "why.reason2Desc": "விடியற்காலை புதிய அறுவடை மற்றும் பண்ணை விவரங்களுடன் இல்லத்திற்கே டெலிவரி.",
    "why.reason3Title": "வெளிப்படையான விலை",
    "why.reason3Desc": "விவசாயிகளே நிர்ணயிக்கும் நியாயமான விலை — வாடிக்கையாளருக்கு சேமிப்பு, விவசாயிக்கு செழிப்பு.",
    "why.reason4Title": "பாதுகாப்பான ஆர்டர் கட்டமைப்பு",
    "why.reason4Desc": "நேரடி கண்காணிப்பு, உடனடி நிலை மற்றும் உண்மையான வாடிக்கையாளர் மதிப்புரைகள்.",
    "why.reason5Title": "விவசாயிகளுக்கான AI வேளாண் ஆலோசகர்",
    "why.reason5Desc": "பயிர் பராமரிப்பு, இயற்கை பூச்சி மேலாண்மை மற்றும் சந்தை விலைக்கு AI வழிகாட்டுதல்.",
    "why.reason6Title": "பன்மொழி அனுபவம்",
    "why.reason6Desc": "தமிழ், கன்னடம், இந்தி, தெலுங்கு, மலையாளம் மற்றும் ஆங்கிலத்தில் முழு குரல் & உரை ஆதரவு.",
    "why.guarantee": "ஆரிக் ஆரோஹி தரநிலை",
    "cta.badge": "நேரடி விவசாயத்தின் எதிர்காலம்",
    "cta.title1": "ஆரிக் ஆரோஹிவுடன் இணையுங்கள்.",
    "cta.title2": "புதிய அறுவடை. நேரடி மதிப்பு.",
    "cta.subtitle": "நியாயமான வருமானம் நாடும் விவசாயியாகவோ அல்லது ஆரோக்கிய உணவு நாடும் வாடிக்கையாளராகவோ இன்றே எங்களுடன் இணையுங்கள்.",
    "cta.exploreProduce": "புதிய பயிர்களைக் காண்க",
