    "about.title1": "നേരിട്ടുള്ള കാർഷിക വാണിജ്യം.",
    "about.title2": "നീതിയിലും വിശ്വാസ്യതയിലും അധിഷ്ഠിതം.",
    "about.subtitle": "പ്രാദേശിക കർഷകരെയും ഉപഭോക്താക്കളെയും നേരിട്ട് ബന്ധിപ്പിക്കുന്ന ആധുനിക കാർഷിക ശൃംഖലയാണ് ഓറിക് ആരോഹി. ഇടനിലക്കാരില്ലാതെ പുലർകാലത്തെ പുതുമയോടെ ജൈവ വിളകൾ ലഭ്യമാക്കുന്നു.",
