    "about.pillar2Desc": "ഓർഡർ ലഭിച്ച ശേഷം മാത്രം വിളവെടുത്ത് ഏതാനും മണിക്കൂറുകൾക്കുള്ളിൽ വീട്ടുപടിക്കൽ എത്തിക്കുന്നു.",
