    "why.subtitle": "കർഷകരെ ശാക്തീകരിക്കാനും ഉപഭോക്താക്കൾക്ക് ഏറ്റവും പുതിയ ജൈവവിളകൾ നൽകാനും ലക്ഷ്യമിടുന്നു.",
    "why.reason1Title": "കർഷകരുമായി നേരിട്ടുള്ള ബന്ധം",
    "why.reason1Desc": "ഇടനിലക്കാരില്ലാതെ കർഷകരിൽ നിന്ന് നേരിട്ട് വാങ്ങി അവരുടെ അധ്വാനത്തിന് പൂർണ്ണ മൂല്യം നൽകുക.",
    "why.reason2Title": "പുതിയതും കണ്ടെത്താവുന്നതുമായ വിളകൾ",
