    "why.reason3Title": "സുതാര്യമായ വില",
    "why.reason3Desc": "കർഷകർ നിശ്ചയിക്കുന്ന ന്യായവില — ഉപഭോക്താവിന് ലാഭം, കർഷകന് സമൃദ്ധി.",
    "why.reason4Title": "സുരക്ഷിതമായ ഓർഡർ സംവിധാനം",
    "why.reason4Desc": "തത്സമയ ട്രാക്കിംഗ്, കൃത്യമായ അവസ്ഥ, യഥാർത്ഥ ഉപഭോക്തൃ അഭിപ്രായങ്ങൾ.",
    "why.reason5Title": "കർഷകർക്കായി AI കാർഷിക സഹായി",
    "why.reason5Desc": "വിള പരിചരണം, ജൈവ കീടനിയന്ത്രണം, വിപണി വില എന്നിവയ്ക്കായി AI നിർദ്ദേശങ്ങൾ.",
    "why.reason6Title": "ബഹുഭാഷാ അനുഭവം",
    "why.reason6Desc": "മലയാളം, കന്നഡ, ഹിന്ദി, തെലുങ്ക്, തമിഴ്, ഇംഗ്ലീഷ് ഭാഷകളിൽ വോയ്‌സ് & ടെക്സ്റ്റ് പിന്തുണ.",
